from sdk.tp.cantp import CanTp
from sdk.bus_app import *


class CCP_UDS:
    def __init__(self):
        self.ccp = ''
        self.b_cli = BGMDOIP()
        self.b_co = self.b_cli.conn("config/DoIPConfig_mcu.json")
        self.bus_tpye = " "
        self.channel = " "
        self.bus_name = " "
        self.can_id_1 = " "
        self.can_id_2 = " "
        self.bitrate = " "

        add_cyclic_msg_with_data_run(0x53F, [0x3F, 0x40, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00], 0.64, "can0", bitrate=500000)
        add_cyclic_msg_with_data_run(0x53F, [0x3F, 0x40, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00], 0.64, "can1", bitrate=500000, is_fd=True)
        add_cyclic_msg_with_data_run(0x53F, [0x3F, 0x40, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00], 0.64, "can2", bitrate=500000)
        add_cyclic_msg_with_data_run(0x53F, [0x3F, 0x40, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00], 0.64, "can3", bitrate=500000)
        add_cyclic_msg_with_data_run(0x53F, [0x3F, 0x40, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00], 0.64, "can4", bitrate=500000)
    
    def run(self,channel,bus_type,canid_1,canid_2,bitrate):
        self.channel = channel
        self.bus_type = bus_type
        self.canid_1 = canid_1
        self.canid_2 = canid_2
        self.bitrate = bitrate

        if self.bus_type in ["can", "canfd"]:
            if self.bus_type == "can":
                self.rx_bus = can.interface.Bus(bustype='socketcan', channel=self.channel, bitrate=self.bitrate)
            else:
                self.rx_bus = can.interface.Bus(bustype='socketcan', channel=self.channel, bitrate=self.bitrate, fd=True)
            self.rx_bus.set_filters([{"can_id": self.canid_1, "can_mask": 0xffff},{"can_id": self.canid_2, "can_mask": 0xffff}])
            self.notifier = can.Notifier(self.rx_bus, [self.can_rx_tx_msg])

        elif self.bus_type == "lin":
                self.rx_bus = can.interface.Bus(bustype='socketcan_native', channel=self.channel, bitrate=self.bitrate)
                self.rx_bus.set_filters([{"can_id": 0x3c, "can_mask": 0xfc}])
                self.notifier = can.Notifier(self.rx_bus, [self.lin_rx_tx_msg])

    def send_ccp(self):
        self.b_cli.session_control(3)
        self.b_cli.write_data_by_identifier(0xF106,self.ccp)
        self.b_cli.close()

    def can_rx_tx_msg(self,msg):
        frame_type = msg.data[1] >> 4
        # logger.info("lin frame_type is {}".format(frame_type))
        pid = msg.arbitration_id

        if pid == 0x132 or pid == 0x340:
              #length, data=CanTp.deconstruct_rx_signal_frames(msg.data)
              print(hex((msg.data)[0]))
           
            #print('收到消息：',msg.data)
            #print('收到消息：',msg.data.decode(encoding='utf-8'))

